import React from "react";

function Settings() {
  const logout = () => {
    localStorage.removeItem(
      "access_token"
    );

    window.location.href = "/";
  };

  return (
    <div style={styles.main}>
      <h1>Settings</h1>

      <div style={styles.card}>
        <h3>User Settings</h3>

        <button
          style={styles.button}
          onClick={logout}
        >
          Logout
        </button>
      </div>
    </div>
  );
}

const styles = {
  main: {
    flex: 1,
    padding: "30px"
  },
  card: {
    background: "#1e293b",
    padding: "20px",
    borderRadius: "10px",
    marginTop: "20px"
  },
  button: {
    marginTop: "20px",
    padding: "10px 20px",
    background: "#ef4444",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer"
  }
};

export default Settings;
